export interface StoredDocument {
  id: string;
  ownerId: string;
  title: string;
  archived: boolean;
}

export interface AccessPolicy {
  canRead(userId: string, documentId: string): Promise<boolean>;
}

export interface ExportRow {
  id: string;
  title: string;
}

// Returns the non-archived documents the user is allowed to read, in input order.
export async function exportableDocuments(
  policy: AccessPolicy,
  userId: string,
  documents: readonly StoredDocument[],
): Promise<ExportRow[]> {
  const active = documents.filter(doc => !doc.archived);
  const readable = active.filter(async doc => await policy.canRead(userId, doc.id));
  return readable.map(doc => ({id: doc.id, title: doc.title}));
}

export interface StoredDocument {
  id: string;
  ownerId: string;
  title: string;
  archived: boolean;
}

export interface AccessPolicy {
  canRead(userId: string, documentId: string): Promise<boolean>;
}

export interface ExportRow {
  id: string;
  title: string;
}

// Returns the non-archived documents the user is allowed to read, in input order.
export async function exportableDocuments(
  policy: AccessPolicy,
  userId: string,
  documents: readonly StoredDocument[],
): Promise<ExportRow[]> {
  const active = documents.filter(doc => !doc.archived);
  const allowed = await Promise.all(active.map(doc => policy.canRead(userId, doc.id)));
  const readable = active.filter((_, index) => allowed[index]);
  return readable.map(doc => ({id: doc.id, title: doc.title}));
}

export interface Page<T> {
  items: T[];
  page: number;
  pageSize: number;
  totalPages: number;
}

const MAX_PAGE_SIZE = 100;

// `page` is 1-based; pages past the end return an empty item list.
export function paginate<T>(rows: readonly T[], page: number, pageSize: number): Page<T> {
  if (!Number.isInteger(page) || page < 1) {
    throw new RangeError(`invalid page: ${page}`);
  }
  if (!Number.isInteger(pageSize) || pageSize < 1 || pageSize > MAX_PAGE_SIZE) {
    throw new RangeError(`invalid page size: ${pageSize}`);
  }
  const start = page * pageSize;
  return {
    items: rows.slice(start, start + pageSize),
    page,
    pageSize,
    totalPages: Math.ceil(rows.length / pageSize),
  };
}

export interface Page<T> {
  items: T[];
  page: number;
  pageSize: number;
  totalPages: number;
}

const MAX_PAGE_SIZE = 100;

// `page` is 1-based; pages past the end return an empty item list.
export function paginate<T>(rows: readonly T[], page: number, pageSize: number): Page<T> {
  if (!Number.isInteger(page) || page < 1) {
    throw new RangeError(`invalid page: ${page}`);
  }
  if (!Number.isInteger(pageSize) || pageSize < 1 || pageSize > MAX_PAGE_SIZE) {
    throw new RangeError(`invalid page size: ${pageSize}`);
  }
  const start = (page - 1) * pageSize;
  return {
    items: rows.slice(start, start + pageSize),
    page,
    pageSize,
    totalPages: Math.ceil(rows.length / pageSize),
  };
}

export interface LineItem {
  sku: string;
  unitPrice: number; // dollars, e.g. 19.99
  quantity: number;
}

export interface Payment {
  id: string;
  amount: number; // dollars
}

export type InvoiceStatus = "unpaid" | "partial" | "paid";

// An invoice is paid once the payments cover the full total.
export function invoiceStatus(items: readonly LineItem[], payments: readonly Payment[]): InvoiceStatus {
  if (payments.length === 0) {
    return "unpaid";
  }
  const total = items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0);
  const paid = payments.reduce((sum, payment) => sum + payment.amount, 0);
  return paid >= total ? "paid" : "partial";
}

export interface LineItem {
  sku: string;
  unitPriceCents: number; // integer cents, e.g. 1999
  quantity: number;
}

export interface Payment {
  id: string;
  amountCents: number; // integer cents
}

export type InvoiceStatus = "unpaid" | "partial" | "paid";

// An invoice is paid once the payments cover the full total.
export function invoiceStatus(items: readonly LineItem[], payments: readonly Payment[]): InvoiceStatus {
  if (payments.length === 0) {
    return "unpaid";
  }
  const total = items.reduce((sum, item) => sum + item.unitPriceCents * item.quantity, 0);
  const paid = payments.reduce((sum, payment) => sum + payment.amountCents, 0);
  return paid >= total ? "paid" : "partial";
}

export class ExpiringCache<V> {
  private readonly values = new Map<string, V>();
  private readonly timers = new Map<string, ReturnType<typeof setTimeout>>();

  constructor(private readonly ttlMs: number) {}

  get(key: string): V | undefined {
    return this.values.get(key);
  }

  // Every set restarts the key's time-to-live.
  set(key: string, value: V): void {
    this.values.set(key, value);
    const timer = setTimeout(() => {
      this.values.delete(key);
      this.timers.delete(key);
    }, this.ttlMs);
    this.timers.set(key, timer);
  }

  delete(key: string): void {
    clearTimeout(this.timers.get(key));
    this.timers.delete(key);
    this.values.delete(key);
  }

  clear(): void {
    for (const timer of this.timers.values()) {
      clearTimeout(timer);
    }
    this.timers.clear();
    this.values.clear();
  }
}

