export interface Session {
  accessToken: string;
  refreshToken: string;
  expiresAt: number; // epoch milliseconds
}

export interface AuthClient {
  // The identity provider rotates refresh tokens: each one can be redeemed only once.
  refresh(refreshToken: string): Promise<Session>;
}

const EXPIRY_MARGIN_MS = 30_000;

export class TokenProvider {
  constructor(private readonly auth: AuthClient, private session: Session) {}

  async accessToken(): Promise<string> {
    if (Date.now() < this.session.expiresAt - EXPIRY_MARGIN_MS) {
      return this.session.accessToken;
    }
    this.session = await this.auth.refresh(this.session.refreshToken);
    return this.session.accessToken;
  }
}

export interface Session {
  accessToken: string;
  refreshToken: string;
  expiresAt: number; // epoch milliseconds
}

export interface AuthClient {
  // The identity provider rotates refresh tokens: each one can be redeemed only once.
  refresh(refreshToken: string): Promise<Session>;
}

const EXPIRY_MARGIN_MS = 30_000;

export class TokenProvider {
  private refreshing: Promise<Session> | undefined;

  constructor(private readonly auth: AuthClient, private session: Session) {}

  async accessToken(): Promise<string> {
    if (Date.now() < this.session.expiresAt - EXPIRY_MARGIN_MS) {
      return this.session.accessToken;
    }
    if (this.refreshing === undefined) {
      this.refreshing = this.auth.refresh(this.session.refreshToken).finally(() => {
        this.refreshing = undefined;
      });
    }
    this.session = await this.refreshing;
    return this.session.accessToken;
  }
}

export interface WebhookEvent {
  id: string;
  type: string;
  createdAt: string;
  data: Record<string, unknown>;
}

export type WebhookHandler = (event: WebhookEvent) => Promise<void>;

export class WebhookDispatcher {
  private readonly handlers = new Map<string, WebhookHandler>();

  on(type: string, handler: WebhookHandler): void {
    this.handlers.set(type, handler);
  }

  off(type: string): void {
    this.handlers.delete(type);
  }

  // The provider adds new event types over time; events without a registered
  // handler are acknowledged and skipped. Returns whether a handler ran.
  async dispatch(event: WebhookEvent): Promise<boolean> {
    const handler = this.handlers.get(event.type)!;
    await handler(event);
    return true;
  }
}

export interface WebhookEvent {
  id: string;
  type: string;
  createdAt: string;
  data: Record<string, unknown>;
}

export type WebhookHandler = (event: WebhookEvent) => Promise<void>;

export class WebhookDispatcher {
  private readonly handlers = new Map<string, WebhookHandler>();

  on(type: string, handler: WebhookHandler): void {
    this.handlers.set(type, handler);
  }

  off(type: string): void {
    this.handlers.delete(type);
  }

  // The provider adds new event types over time; events without a registered
  // handler are acknowledged and skipped. Returns whether a handler ran.
  async dispatch(event: WebhookEvent): Promise<boolean> {
    const handler = this.handlers.get(event.type);
    if (handler === undefined) {
      return false;
    }
    await handler(event);
    return true;
  }
}

export interface Db {
  query<T>(sql: string, params: readonly unknown[]): Promise<T[]>;
}

export interface OrderSummary {
  id: string;
  customerName: string;
  totalCents: number;
  createdAt: Date;
}

export interface ListOrdersQuery {
  customerId: string;
  sortBy?: string; // taken from the request query string, e.g. "created_at"
  descending?: boolean;
}

export async function listOrders(db: Db, query: ListOrdersQuery): Promise<OrderSummary[]> {
  const sortBy = query.sortBy ?? "created_at";
  const direction = query.descending ? "DESC" : "ASC";
  const sql = `SELECT id, customer_name AS "customerName", total_cents AS "totalCents", created_at AS "createdAt"
     FROM orders
    WHERE customer_id = $1
    ORDER BY ${sortBy} ${direction}
    LIMIT 100`;
  return db.query<OrderSummary>(sql, [query.customerId]);
}

export interface Db {
  query<T>(sql: string, params: readonly unknown[]): Promise<T[]>;
}

export interface OrderSummary {
  id: string;
  customerName: string;
  totalCents: number;
  createdAt: Date;
}

export interface ListOrdersQuery {
  customerId: string;
  sortBy?: string; // taken from the request query string, e.g. "created_at"
  descending?: boolean;
}

const SORTABLE_COLUMNS: ReadonlySet<string> = new Set(["created_at", "total_cents", "customer_name"]);

export async function listOrders(db: Db, query: ListOrdersQuery): Promise<OrderSummary[]> {
  const sortBy = query.sortBy !== undefined && SORTABLE_COLUMNS.has(query.sortBy) ? query.sortBy : "created_at";
  const direction = query.descending ? "DESC" : "ASC";
  const sql = `SELECT id, customer_name AS "customerName", total_cents AS "totalCents", created_at AS "createdAt"
     FROM orders
    WHERE customer_id = $1
    ORDER BY ${sortBy} ${direction}
    LIMIT 100`;
  return db.query<OrderSummary>(sql, [query.customerId]);
}

export enum Plan {
  Free,
  Team,
  Enterprise,
}

export interface PlanOption {
  label: string;
  value: Plan;
}

const LABELS: Record<Plan, string> = {
  [Plan.Free]: "Free",
  [Plan.Team]: "Team",
  [Plan.Enterprise]: "Enterprise",
};

// One option per plan, in declaration order, for the billing settings dropdown.
export function planOptions(): PlanOption[] {
  return Object.values(Plan).map(value => ({label: LABELS[value as Plan], value: value as Plan}));
}

export enum Plan {
  Free,
  Team,
  Enterprise,
}

export interface PlanOption {
  label: string;
  value: Plan;
}

const LABELS: Record<Plan, string> = {
  [Plan.Free]: "Free",
  [Plan.Team]: "Team",
  [Plan.Enterprise]: "Enterprise",
};

// One option per plan, in declaration order, for the billing settings dropdown.
export function planOptions(): PlanOption[] {
  return Object.values(Plan)
    .filter((value): value is Plan => typeof value === "number")
    .map(value => ({label: LABELS[value], value}));
}
